import React, { useState, useEffect } from 'react';
import { Container, Button, Input, InputGroup, InputGroupText } from 'reactstrap';

const ChatRoom = ({ chatId, otherUserId, loginUserId, goBack }) => {
    const [message, setMessage] = useState('');
    const [messages, setMessages] = useState([]);

    useEffect(() => {
        fetchMessages(chatId);
    }, [chatId]);

    const fetchMessages = async (headerId) => {
        try {
            const response = await fetch(`http://localhost:8080/api/messages/byHeaderId/${headerId}`);
            const data = await response.json();
            setMessages(data);
        } catch (error) {
            console.error('Error:', error);
        }
    };

    const handleSend = async () => {
        if (message.trim() !== '') {
            const newMessage = {
                headerId: chatId,
                fromId: loginUserId,
                toId: otherUserId,
                content: message.trim(),
                time: new Date().toISOString(),
            };
            setMessages([...messages, newMessage]);
            setMessage('');
            try {
                const response = await fetch('http://localhost:8080/api/messages', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(newMessage),
                });
                await response.json();
            } catch (error) {
                console.error('Error:', error);
            }
        }
    };

    return (
        <Container style={{ position: 'relative', height: '100vh', padding: '0' }}>
            <Button style={{ position: 'absolute', top: '10px', left: '10px' }} color="secondary" onClick={goBack}>
                뒤로가기
            </Button>
            <div style={{ marginTop: '50px', overflowY: 'auto', height: 'calc(100vh - 120px)' }}>
                {messages.map((msg, index) => (
                    <div
                        key={index}
                        style={{
                            display: 'flex',
                            justifyContent: msg.fromId === loginUserId ? 'flex-end' : 'flex-start',
                            padding: '10px',
                        }}
                    >
                        <div
                            style={{
                                maxWidth: '60%',
                                borderRadius: '12px',
                                padding: '10px',
                                backgroundColor: msg.fromId === loginUserId ? '#007bff' : '#f1f0f0',
                                color: msg.fromId === loginUserId ? 'white' : 'black',
                            }}
                        >
                            {msg.content}
                        </div>
                    </div>
                ))}
            </div>
            <InputGroup style={{ position: 'absolute', bottom: '10px', left: '0', width: '100%' }}>
                <Input
                    type="text"
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    placeholder="메시지를 입력하세요"
                />
                <InputGroupText>
                    <Button color="primary" onClick={handleSend}>
                        전송
                    </Button>
                </InputGroupText>
            </InputGroup>
        </Container>
    );
};

export default ChatRoom;
